import json, re
from docx import Document

TEMPLATE = '/root/offer_letter_template.docx'
DATA_PATH = '/root/employee_data.json'
OUTPUT = '/root/offer_letter_filled.docx'

with open(DATA_PATH, 'r') as f:
    data = json.load(f)

relocation_yes = str(data.get('RELOCATION_PACKAGE','')).strip().lower() == 'yes'

# helper to delete a paragraph
def delete_paragraph(paragraph):
    p = paragraph._element
    p.getparent().remove(p)
    paragraph._p = paragraph._element = None

# replace placeholders in paragraph (robust to split runs)
def replace_in_paragraph(para):
    text = para.text
    if not text:
        return
    # replace placeholders
    new_text = text
    for key, value in data.items():
        placeholder = '{{' + key + '}}'
        if placeholder in new_text:
            new_text = new_text.replace(placeholder, str(value))

    # handle relocation markers
    if relocation_yes:
        new_text = new_text.replace('{{IF_RELOCATION}}','').replace('{{END_IF_RELOCATION}}','')
    # if relocation no, we would remove section, but not needed for this task

    if new_text != text:
        runs = para.runs
        if runs:
            runs[0].text = new_text
            for r in runs[1:]:
                r.text = ''

# process list of paragraphs and remove empty marker-only paragraphs

def process_paragraphs(paragraphs):
    for para in list(paragraphs):
        replace_in_paragraph(para)
        # remove paragraph if now empty (after marker removal)
        if para.text is not None and para.text.strip() == '':
            # avoid deleting paragraphs that might be intentionally empty? here ok
            delete_paragraph(para)

# process tables recursively

def process_table(table):
    for row in table.rows:
        for cell in row.cells:
            process_paragraphs(cell.paragraphs)
            for nested in cell.tables:
                process_table(nested)


doc = Document(TEMPLATE)

# body paragraphs
process_paragraphs(doc.paragraphs)
# tables
for table in doc.tables:
    process_table(table)

# headers/footers
for section in doc.sections:
    process_paragraphs(section.header.paragraphs)
    process_paragraphs(section.footer.paragraphs)
    # headers/footers tables
    for table in section.header.tables:
        process_table(table)
    for table in section.footer.tables:
        process_table(table)

doc.save(OUTPUT)
print('Saved to', OUTPUT)
